import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Prop,
	State,
	h,
} from "@stencil/core";
import { dotsSix } from "../../../icons";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import {
	ColumnService,
	type ColumnServiceInterface,
	type ColumnType,
} from "./column.service";
import { type GroupServiceInterface } from "./group.service";
import { type RowReorderServiceInterface } from "./rowReorder.service";
import { getIconAsset } from "./table.util";
import { TreeService, type TreeServiceInterface } from "./tree.service";
import { type StickyHeaderServiceInterface } from "./sticky-header.service"


/**
 * @since 2.14.7
 * @status stable
 *
 * @data-testid sort-icon-button - The column sort control rendered for sortable headers.
 *
 * @part base - The component's base wrapper.
 * @part left-border - The component's left-border.
 * @part right-border - The component's right-border.
 * @part table - The table tag.
 * @part thead - The thead tag.
 * @part tbody - The tbody tag.
 * @part resizer - The column resizer element.
 * @part sort-button - The sorting button element.
 */
@Component({
	tag: "hbr-dom-table",
	styleUrl: "dom-table.scss",
	shadow: true,
})
export class DomTable {
	columnService: ColumnServiceInterface;
	stickyHeaderService: StickyHeaderServiceInterface;
	rowReorderService: RowReorderServiceInterface;
	treeService: TreeServiceInterface;
	groupService: GroupServiceInterface;
	@State() isColReordering: boolean;
	@State() reRender = false;
	@Element() host: HTMLElement;

	// @ts-ignore
	private stickyHeaderRef: HTMLDivElement;
	// @ts-ignore
	private tableWrapperRef: HTMLDivElement;

	desnitySize = {
		condensed: 4,
		compact: 8,
		comfy: 12,
		spacious: 16,
	};

	/** Default layout is left aligned, setting autoLayout to true will make the table auto span. */
	@Prop({ reflect: true }) autoLayout?: boolean = false;

	/** Column configurations. */
	// When using hbr-dom-table in vanilla js, set columns via javascript
	@Prop() columns: Array<ColumnType> = [];

	/** Data to be displayed in the table. */
	// When using hbr-dom-table in vanilla js, set data via javascript
	@Prop() data = [];

	/** If true, the table will be rendered as a tree structure. */
	@Prop({ reflect: true }) tree?: boolean = false;

	/** Opened tree nodes, used for tree structure. */
	@Prop() opened?: string[] = [];

	/** Selected rows, used for row selection. */
	@Prop() selected?: string[] = [];

	/** Expanded rows, used for expandable rows. */
	@Prop() expanded?: string[] = [];

	/** Enable row level hover state. */
	@Prop({ reflect: true }) rowLevel?: boolean = false;

	/** Aria label for the table. */
	@Prop() aria? = {
		label: "",
	};

	/** Table density. */
	@Prop({ reflect: true }) density?:
		| "condensed"
		| "compact"
		| "comfy"
		| "spacious" = "compact";

	/** Enable sticky header that remains visible when scrolling. */
	@Prop({ reflect: true }) stickyHeader?: boolean = false;

	/** Emitted when the user starts drop a row.  */
	@Event({ eventName: "hbr-row-reorder" }) rowReorderDrop: EventEmitter;

	/** Emitted when the user starts drop a column.  */
	@Event({ eventName: "hbr-column-reorder" }) reorderDrop: EventEmitter;

	/** Emitted after the user resized a column.  */
	@Event({ eventName: "hbr-column-resize" }) columnResize: EventEmitter;

	/** Emitted when the user click the header sort button.  */
	@Event({ eventName: "hbr-sort" }) customSort: EventEmitter;

	/** Emitted when the user click row.  */
	@Event({ eventName: "hbr-row-click" }) rowClick: EventEmitter;

	disconnectedCallback() {
		if (this.columnService) {
			this.columnService.clearSubscriptions();
		}
	}

	componentWillLoad() {
		this.columnService = new ColumnService(this);
	}

	componentWillRender() {
		if (this.tree) {
			this.treeService = new TreeService(this);
		}
		this.columnService.findPinBorder();
	}

	componentDidRender() {
		this.columnService.setColPinShadow();
		this.stickyHeader && this.stickyHeaderService.syncWidth();
	}

	renderHeaderRows = (isSticky = false) => {
		const slotPrefix = isSticky && this.stickyHeader ? "sticky-" : "";
		const shouldBeInert = this.stickyHeader && !isSticky;
		return [
			this.groupService.renderGroup(isSticky),
			<tr
				class={{ "dom-table-tr--dragging": this.isColReordering }}
				{...this.columnService.reorderEndEvents()}
				{...(shouldBeInert ? { inert: true } : {})}
			>
				{this.columnService.getColumns().map((column, colIdx) => (
					<th
						key={`column-${column.id}`}
						role={column.noRows ? "none" : null}
						data-id={column.id}
						aria-hidden={column.id === "empty" ? "true" : undefined}
						class={{
							[`dom-table__col-pin-${column.pin}`]: !!column.pin,
							"dom-table-header--sortable": column.sortable,
							"dom-table-header--resizable": column.resizable,
							"dom-table-header--resizing":
								column === this.columnService.resizingColumn,
							...this.columnService.getPinClassName(colIdx),
							...this.groupService.getGroupClassName(column),
						}}
						ref={(ref) => {
							if (ref) {
								this[`th-${column.id}`] = ref;
								this.columnService.setPinOffset(column, colIdx, ref);
								this.columnService.setWidth(column, ref);
								this.columnService.reorder(column, ref);
								this.columnService.sort(column, ref);
							}
						}}
						aria-sort={
							column.order === "asc"
								? "ascending"
								: column.order === "desc"
									? "descending"
									: null
						}
					>
						<slot name={`${slotPrefix}column-${column.id}-th`}>
							<div
								part="base"
								class={{
									"dom-table-header": true,
									"dom-table-header-gap":
										this.host?.querySelector(
											`[slot="${slotPrefix}column-${column.id}-bottom"]`
										) !== null,
								}}
							>
								<div
									class={{
										"dom-table-header--top": true,
										"dom-table-header--align-left": !column.align,
										"dom-table-header--align-center":
											column.align === "center",
										"dom-table-header--align-right": column.align === "right",
									}}
								>
									<slot name={`${slotPrefix}column-${column.id}-prefix`} />
									{column.sortable ? (
										<button
											type="button"
											part="sort-button"
											data-testid="sort-button"
											class="dom-table__sort-button"
											tabIndex={-1}
											id={`${slotPrefix}column-${column.id}-sort-button-text`}
										>
											<slot name={`${slotPrefix}column-${column.id}`}>
												{column.name}
											</slot>
										</button>
									) : (
										<slot name={`${slotPrefix}column-${column.id}`}>
											{column.name}
										</slot>
									)}
									<slot name={`${slotPrefix}column-${column.id}-suffix`} />
									<slot name={`${slotPrefix}column-${column.id}-sort-icon`}>
										{column.sortable && (
											<button
												class="dom-table__sort-button"
												aria-describedby={`${slotPrefix}column-${column.id}-sort-button-text`}
												data-testid="sort-icon-button"
											>
												<hbr-icon
													class={{
														"dom-table-header__sort-icon": true,
														"dom-table-header__sort-icon-default":
															!column.order,
														"dom-table-header__sort-icon--asc":
															column.order === "asc",
														"dom-table-header__sort-icon--desc":
															column.order === "desc",
													}}
													asset={getIconAsset(column.order)}
												/>
											</button>
										)}
									</slot>
								</div>
								<div
									class="dom-table-header--bottom"
									onClick={(event) => {
										event.stopPropagation();
									}}
								>
									<slot name={`${slotPrefix}column-${column.id}-bottom`} />
								</div>
								{column.resizable && (
									<span
										part="resizer"
										class="dom-table__resizer"
										data-resize="true"
										onMouseDown={(event) => {
											const th = (event.target as HTMLElement).closest("th");
											this.columnService.resizingTh = th;
											this.columnService.resizingColumn = column;
										}}
									/>
								)}
							</div>
						</slot>
					</th>
				))}
			</tr>
		]
	}

	renderHeader = () => {
		return (
			<thead part="thead">
				{this.renderHeaderRows()}
				{this.stickyHeader && <div
					ref={(el) => {
						this.stickyHeaderRef = el
					}}
					class="dom-table__sticky-header"
				>
					{this.renderHeaderRows(true)}
				</div>}
			</thead>
		);
	};

	renderRows = () => {
		if (this.tree) {
			return this.treeService.getTree();
		}
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const list = [];
		const columns = this.columnService.getColumns();
		for (let i = 0; i < this.data.length; i++) {
			const id = this.data[i].id;
			list.push(
				<tr
					key={`row-${id}`}
					class={{
						"dom-table__row-selected": this.selected.includes(id),
						"dom-table__row-level": this.rowLevel,
					}}
					onClick={this.columnService.rowLevelClick(this.data[i])}
					ref={(ref) => {
						if (ref) {
							this.rowReorderService.rowReorder(id, ref);
						}
					}}
					data-id={id}
				>
					{columns.map((column, colIdx) => {
						const className = column.noRows
							? {}
							: this.columnService.getPinClassName(colIdx);
						return (
							<td
								aria-hidden={
									column.id === "empty" || column.noRows ? "true" : undefined
								}
								key={`row-${id}-column-${column.id}`}
								class={{
									"dom-table__td-align-center": column.align === "center",
									"dom-table__td-align-right": column.align === "right",
									[`dom-table__col-pin-${column.pin}`]:
										!column.noRows && !!column.pin,
									...className,
								}}
								ref={(ref) => {
									ref && this.columnService.setPinOffset(column, colIdx, ref);
								}}
							>
								<slot name={`row-${id}-column-${column.id}`}>
									{this.data[i][column.prop || column.id]}
								</slot>
								{column.rowReorder && (
									<hbr-button size="xsmall" variant="text" class="dom-table--row-drag-icon">
										<hbr-icon asset={customSystemIcons?.["dots-six"] || dotsSix} />
									</hbr-button>
								)}
							</td>
						);
					})}
				</tr>,
			);
			if (this.data[i].expandable && this.expanded.includes(id)) {
				list.push(
					<tr key={`row-${id}-expandable`} data-expandable-row>
						<td colSpan={this.columnService.getColumns().length}>
							<slot name={`row-${id}-expandable`} />
						</td>
					</tr>,
				);
			}
		}
		return list;
	};

	render() {
		return (
			<Host>
				<div
					part="left-border"
					class={{ "left-border": this.columnService.pinLeftBorder === -1 }}
				/>
				<div
					part="base"
					class={{
						wrapper: true,
						"wrapper__sticky-header": this.stickyHeader,
					}}
					ref={(el) => (this.tableWrapperRef = el)}
					onScroll={e => {
						if (this.stickyHeader) {
							// Only handle horizontal scroll sync
							this.stickyHeaderService.syncScrollLeft(e);
						}
					}}
				>
					<table
						part="table"
						role={this.tree ? "treegrid" : undefined}
						aria-label={this.aria?.label ? this.aria?.label : undefined}
						class={{
							[`dom-table--density-${this.density}`]: true,
							"dom-table--auto-layout": this.autoLayout,
							"dom-table__empty": !this.data.length,
						}}
					>
						{this.renderHeader()}
						<tbody
							part="tbody"
							{...this.rowReorderService.dropEvent()}
						>
							{this.data.length ? (
								this.renderRows()
							) : (
								<tr class="dom-table__empty-row">
									<td colSpan={this.columnService.getColumns().length}>
										<slot name="empty" />
									</td>
								</tr>
							)}
						</tbody>
					</table>
				</div>
				<div data-drag-image />
				<div
					part="right-border"
					class={{ "right-border": this.columnService.pinRightBorder === -1 }}
				/>
			</Host>
		);
	}
}
