import {sortUp, sortDown, sort} from "../../../icons";

export const rotateOrder = (currentOrder) => {
  switch (currentOrder) {
    case "asc":
      return "desc";
    case "desc":
      return undefined;
    case undefined:
      return "asc";
    default:
      return "asc";
  }
};

export const isNumeric = (num: any) =>
  (typeof num === "number" || (typeof num === "string" && num.trim() !== "")) &&
  !isNaN(num as number);

export const getIconAsset = (order) =>
  order === "asc" ? sortDown : order === "desc" ? sortUp : sort;
