import {h} from "@stencil/core"
import { dotsSix } from "../../../icons";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

export interface TreeServiceInterface {
  table: any;
  renderTreeRow: ({data, level, idx, children}) => JSX.Element;
  renderTreeList: ({treeList, level, data}) => void;
  getTree: () => any[];
}

export class TreeService implements TreeServiceInterface {
  table: any;
  constructor(self) {
    this.table = self;
  }

  renderTreeRow = ({data, level, idx, children}) => {
    const customSystemIcons = getBootstrapConfig()?.systemIcons;
    const isParent = Array.isArray(children);
    return (
      <tr
        key={data.id}
        aria-level={level + 1}
        aria-setsize={isParent ? children.length || 1 : 1}
        aria-posinset={idx + 1}
        aria-expanded={
          isParent
            ? this.table.opened.includes(data.id)
              ? "true"
              : "false"
            : undefined
        }
        class={{
          "dom-table__tree-children": level > 0,
          "dom-table__row-selected": this.table.selected.includes(data.id),
          "dom-table__row-level": this.table.rowLevel,
        }}
        ref={(ref) => {
          if (ref) {
            level === 0 && this.table.rowReorderService.rowReorder(data.id, ref);
          }
        }}
        onClick={this.table.columnService.rowLevelClick(data)}
        data-id={data.id}
      >
        {this.table.columnService.getColumns().map((column, colIdx) => {
          const isRowDrag = level === 0 && column.rowReorder
          const className = column.noRows
            ? {}
            : this.table.columnService.getPinClassName(colIdx);
          return (
            <td
              key={`row-${data.id}-column-${column.id}`}
              role="gridcell"
              class={{
                [`dom-table__col-pin-${column.pin}`]: !column.noRows && !!column.pin,
                "dom-table__row-selected": this.table.selected.includes(data.id),
                "dom-table__td-align-center": column.align === "center",
                "dom-table__td-align-right": column.align === "right",
                ...className,
              }}
              ref={(ref) => {
                ref && this.table.columnService.setPinOffset(column, colIdx, ref);
              }}
            >
              <slot name={`row-${data.id}-column-${column.id}`} >
                {isRowDrag ? null : data[column.prop || column.id]}
              </slot>
              {isRowDrag &&
                <hbr-button size="xsmall" variant="text" class="dom-table--row-drag-icon">
                  <hbr-icon asset={customSystemIcons?.["dots-six"] || dotsSix} />
                </hbr-button>
              }
            </td>
          );
        })}
      </tr>
    );
  };

  renderTreeList = ({treeList, level, data}) => {
    if (level === 0) {
      treeList.push(
        this.renderTreeRow({
          data,
          level,
          idx: 0,
          children: data.children,
        })
      );
    }
    if (data.expandable && this.table.expanded.includes(data.id)) {
      treeList.push(
        <tr key={`row-${data.id}-expandable`} data-expandable-row>
          <td colSpan={this.table.columnService.getColumns().length}>
            <slot name={`row-${data.id}-expandable`}></slot>
          </td>
        </tr>
      );
    }
    if (!this.table.opened.includes(data.id)) return;
    level++;
    data.children.forEach((child, idx) => {
      treeList.push(
        this.renderTreeRow({
          data: child,
          idx,
          children: data.children,
          level,
        })
      );
      if (child.children) {
        this.renderTreeList({
          treeList,
          data: child,
          level,
        });
      }
    });
  };

  getTree = () => {
    return this.table.data.map((data) => {
      const treeList = [];
      this.renderTreeList({
        treeList,
        data,
        level: 0,
      });
      return treeList;
    });
  }
}