import {h} from "@stencil/core";
import {type ColumnType, type ColumnServiceInterface} from "./column.service";

export interface GroupServiceInterface {
  table: any;
  renderGroup: (isSticky: boolean) => JSX.Element | null;
  isGroup: (col: string | ColumnType) => boolean;
  getGroup: (col: string | ColumnType) => ColumnType | undefined;
  hasGroup: () => boolean;
  columnService: ColumnServiceInterface;
  getGroupClassName: (col: ColumnType) => Record<string, boolean>;
  isFirstOfTheGroup: (column: ColumnType) => boolean;
  isLastOfTheGroup: (column: ColumnType) => boolean;
  getVisibleColumns: (list: any[]) => any[];
  getItemInGroup: (id: string | ColumnType) => any;
}

export class GroupService implements GroupServiceInterface {
  table: any;
  columnService: ColumnServiceInterface;
  constructor(self, columnService) {
    this.table = self;
    this.columnService = columnService;
  }

  getGroup = (col: ColumnType | string) => {
    let hasChild: ColumnType | undefined;
    if (typeof col === "string") {
      return this.table.columns.find((c) => !c.hidden && c.id === col);
    } else if (typeof col === "object" && Array.isArray(col.group)) {
      if (col.group.length && !col.hidden) {
        return col;
      }
    }
    return hasChild;
  }

  isGroup = (col: string | ColumnType) => {
    return !!this.getGroup(col)
  };

  getItemInGroup = (col: ColumnType | string) => {
    let group = false;
    this.table.columns.forEach((column) => {
      if (Array.isArray(column.group) && column.group.length) {
        column.group.forEach((child) => {
          if (typeof col === "string" && child.id === col) {
            group = column
          } else if (typeof col === "object" && child === col) {
            group = column;
          }
        })
      }
    })
    return group
  }

  hasGroup = () => {
    return this.table.columns.some(this.isGroup);
  };

  renderGroup = (isSticky) => {
    const hasGroup = this.hasGroup();
    if (!hasGroup) {
      return null;
    }
    const shouldBeInert = this.table.stickyHeader && !isSticky;
    const rows = [];
    this.table.columns.forEach((col) => {
      if (this.isGroup(col)) {
        const colSpan = col.group.filter((child) => {
          return this.columnService
            .getColumns()
            .find((column) => column.id === child.id);
        }).length;
        if (colSpan) {
          rows.push(
            <th
              class={{
                "dom-table__group-th": true,
                "dom-table__group-header": true,
                "dom-table__group-reorderable": col.reorderable
              }}
              key={`group-${col.id}`}
              colSpan={colSpan}
              scope="colgroup"
              data-id={col.id}
              ref={ref => {
                if (ref) {
                  this.columnService.reorder(col, ref);
                }
              }}
            >
              <slot name={`group-${col.id}`}>{col.name}</slot>
            </th>
          );
        }
      } else {
        if (this.columnService.getColumns().find((c) => c.id === col.id)) {
          rows.push(
            <th
              class="dom-table__group-th"
              key={`group-${col.id}`}
              colSpan={1}
            ></th>
          );
        }
      }
    });
    return <tr
        class={{
          "dom-table-tr--dragging": this.table.isColReordering,
        }}
        {...(shouldBeInert ? { inert: true } : {})}
        {...this.columnService.reorderEndEvents()}
      >{rows}</tr>;
  };

  isFirstOfTheGroup = (column: ColumnType) => {
    let isFirst = false;
    this.table.columns.forEach((col) => {
      if (Array.isArray(col.group)) {
        const group = this.getVisibleColumns(col.group);
        if (group.length && group[0].id === column.id) {
          isFirst = true;
        }
      }
    })
    return isFirst
  }

  getVisibleColumns = (children) => {
    const list = []
    children.forEach((col: any) => {
      const column = this.columnService.getColumns().find((c: ColumnType) => c.id === col.id);
      if (column) {
        list.push(column);
      }
    })
    return list
  }

  isLastOfTheGroup = (column: ColumnType) => {
    let isLast = false;
    this.table.columns.forEach((col) => {
      if (Array.isArray(col.group)) {
        const group = this.getVisibleColumns(col.group);
        if (group.length && group[group.length - 1].id === column.id) {
          isLast = true;
        }
      }
    })
    return isLast
  }

  getGroupClassName = (col: ColumnType) => {
    return {
      "dom-table__group-left-border": this.isFirstOfTheGroup(col),
      "dom-table__group-right-border": this.isLastOfTheGroup(col)
    }
  }
}
