import {isNumeric} from "./table.util";
import {type ReorderServiceInterface, ReorderService} from "./reorder.service";
import {type RowReorderServiceInterface, RowReorderService} from "./rowReorder.service";
import {GroupService} from "./group.service";
import {rotateOrder} from "./table.util"
import {StickyHeaderService} from "./sticky-header.service";

export type ColumnType = {
  id: string;
  name?: string;
  type?: "string" | "number" | "date"; // The data type of the column.
  prop?: string; // The property name to match to the data.
  align?: "left" | "center" | "right";
  order?: "asc" | "desc" | undefined;
  sortable?: boolean | undefined;
  resizable?: boolean | undefined;
  reorderable?: boolean | undefined;
  skipRotateOrder?: boolean | undefined;
  width?: number | string | undefined;
  minWidth?: number | undefined;
  maxWidth?: number | undefined;
  hidden?: boolean | undefined;
  pin?: "left" | "right" | undefined;
  noRows?: boolean | undefined; // if true, the rows of the column will be a11y hidden
  [key: string]: any;
}

export type Subscription = {
  target: Element | Document | Window;
	callback(...params: any[]): void;
	options?: AddEventListenerOptions;
}
export interface ColumnServiceInterface {
  table: any;
  pinLeftBorder: number;
  pinRightBorder: number;
  resizingTh: HTMLElement | undefined;
  resizingColumn: ColumnType | undefined;
  findPinBorder: () => void;
  setColPinShadow: () => void;
  setPinOffset: (column: ColumnType, colIdx: number, element: HTMLElement) => void;
  getPinClassName: (colIdx: number) => any;
  scrollNotAtRight: (ele: HTMLElement) => boolean;
  scrollNotAtLeft: (ele: HTMLElement) => boolean;
  resize: (e: MouseEvent) => void;
  cleanResize: () => void;
  setWidth: (column: ColumnType, element: HTMLElement) => void;
  reorder: (column: ColumnType, element: HTMLElement) => void;
  sort: (column: ColumnType, element: HTMLElement) => void;
  reorderEndEvents: () => any;
  subscriptions: Record<string, Subscription>;
  clearSubscriptions: () => void;
  getColumns: () => ColumnType[];
  applyPinOffset: (pinCols: ColumnType[], column: ColumnType, element: HTMLElement, pin?: "left" | "right") => void;
  subscribe: () => void;
  reorderService: ReorderServiceInterface;
  rowLevelClick: (data: any) => (event: MouseEvent) => void;
  getColumnPin: (columnId: string) => "left" | "right" | undefined;
}


export class ColumnService implements ColumnServiceInterface {
  table;
  pinLeftBorder = -1;
  pinRightBorder = -1;
  resizingColumn = undefined
  resizingTh = undefined
  reorderService: ReorderServiceInterface
  rowReorderService: RowReorderServiceInterface
  subscriptions = {}
  constructor(self) {
    this.table = self
    this.reorderService = new ReorderService(self, this)
    this.table.rowReorderService = this.rowReorderService = new RowReorderService(self, this);
    this.table.groupService = new GroupService(self, this);
    this.subscriptions = {
      resize: {
        target: window,
        callback: this.setColPinShadow
      },
      mousemove: {
        target: document,
        callback: this.resize
      },
      mouseup: {
        target: document,
        callback: this.cleanResize
      },
    }
    if (this.table.stickyHeader) {
      new StickyHeaderService(this.table, this)
		}
    this.subscribe()
  }
  findPinBorder = () => {
    this.pinLeftBorder = this.table.columns?.filter(col => !col.hidden).findLastIndex((column: ColumnType) => column?.pin === "left");
    this.pinRightBorder = this.getColumns().findIndex((column: ColumnType) => column?.pin === "right");
  }

  scrollNotAtRight(ele: HTMLElement): boolean {
    const scrollableWidth = ele.scrollWidth - ele.clientWidth;
    return Math.ceil(ele.scrollLeft) < scrollableWidth;
  }

  scrollNotAtLeft(ele: HTMLElement): boolean {
    return ele.scrollLeft > 0;
  }

  setColPinShadow = () => {
    const target = this.table.host.shadowRoot.querySelector(".wrapper") as HTMLElement;
    if (target && "scrollLeft" in target) {
      const isPinRightShadow = this.scrollNotAtRight(target)
      const isPinLeftShadow = this.scrollNotAtLeft(target)
      this.table.host.style.setProperty('--col-pin-left-border-shadow', isPinLeftShadow ? "var(--col-pin-left-shadow)" : "none");
      this.table.host.style.setProperty('--col-pin-right-border-shadow', isPinRightShadow ? "var(--col-pin-right-shadow)" : "none");
    }
  }

  applyPinOffset = (pinCols: ColumnType[], column: ColumnType, element: HTMLElement, pin: "left" | "right" = "left") => {
    const leftOffset = pinCols
      .filter((col: ColumnType) => col.pin === pin && col.id !== column.id)
      .reduce((acc: number, column: ColumnType) => {
        let width: number = 0
        if (isNumeric(column.width)) {
          width = column.width as number
        }
        let ele = this.table[`th-${column.id}`] as HTMLElement
        if (!ele) {
          ele = this.table.host.shadowRoot.querySelector(`th[data-id="${column.id}"]`) as HTMLElement
        }
        if (ele) {
          width = Math.max(ele.offsetWidth, width)
        }
        return acc += width
      }, 0);
    element.style.setProperty(`--col-pin-${pin}-offset`, `${leftOffset}px`)
  }

  setPinOffset = (column: ColumnType, colIdx: number, element: HTMLElement) => {
    if (!element) return
    setTimeout(() => {
      if (column.pin === "left") {
        const pinCols = this.getColumns().slice(0, colIdx + 1)
        this.applyPinOffset(pinCols, column, element, "left")
      } else if (column.pin === "right") {
        const pinCols = this.getColumns().slice(colIdx + 1).toReversed()
        this.applyPinOffset(pinCols, column, element, "right")
      }
    })
  }

  setWidth = (column: ColumnType, element: HTMLElement) => {
    if (typeof column.minWidth === "number") {
      element.style.minWidth = column.minWidth + "px";
    }
    if (typeof column.width === "number") {
      element.style.width = column.width + "px";
      element.style.minWidth = column.width + "px";
    } else if (typeof column.width === "string") {
      element.style.width = column.width
      element.style.minWidth = column.width
    }
    if (typeof column.maxWidth === "number") {
      element.style.maxWidth = column.maxWidth + "px";
    }
  }

  getPinClassName = (colIdx: number) => {
    return {
      "dom-table__col-pin-left-border": this.pinLeftBorder === colIdx,
      "dom-table__col-pin-right-border": this.pinRightBorder === colIdx,
    }
  }

  getColumns = () => {
    return this.table.columns.reduce((acc: ColumnType[], column: ColumnType) => {
      if (Array.isArray(column.group)) {
        const groupColumns = column.group.filter(col => !col.hidden)
        if (column.hidden) {
          return acc;
        }
        return [...acc, ...groupColumns];
      } else {
        if (!column.hidden) {
          acc.push(column);
        }
        return acc;
      }
    }, []);
  }

  resize = (e: MouseEvent) => {
    if (this.resizingColumn) {
      const th = this.resizingTh;
      const newWidth = e.clientX - th.getBoundingClientRect().left + 2;
      const minWidth = this.resizingColumn.minWidth
      if (isNumeric(minWidth) && newWidth < minWidth) {
        return;
      }
      const maxWidth = this.resizingColumn.maxWidth
      if (isNumeric(maxWidth) && maxWidth < newWidth) {
        return;
      }
      this.resizingColumn.width = newWidth;
      th.style.minWidth = `${newWidth}px`;
      th.style.width = `${newWidth}px`;
    }
    if (["left", "right"].includes(this.resizingColumn?.pin)) {
      this.table.reRender = !this.table.reRender
    }
  }

  cleanResize = () => {
    if (["left", "right"].includes(this.resizingColumn?.pin)) {
      this.table.reRender = !this.table.reRender
    }
    if (this.resizingColumn) {
      this.table.columnResize.emit({
        column: {...this.resizingColumn}
      })
    }
    setTimeout(() => {
      this.resizingColumn = undefined;
      this.resizingTh = undefined;
    })
  }

  reorder(column: ColumnType, element: HTMLElement) {
    this.reorderService.colReorder(column, element);
  }

  reorderEndEvents() {
    return this.reorderService.colsReorder()
  }

  handleSort = (column) => {
    const prop = column.prop || column.id;
    if (column.type === "string") {
      return (a, b) => {
        const valA = a[prop] ?? "";
        const valB = b[prop] ?? "";

        if (column.order === "asc") {
          return String(valA).localeCompare(String(valB));
        } else if (column.order === "desc") {
          return String(valB).localeCompare(String(valA));
        } else {
          return 0;
        }
      };
    } else if (column.type === "number") {
      return (a, b) => {
        const valA = Number(a[prop]);
        const valB = Number(b[prop]);

        if (isNaN(valA) || isNaN(valB)) return 0;

        if (column.order === "asc") {
          return valA - valB;
        } else if (column.order === "desc") {
          return valB - valA;
        } else {
          return 0;
        }
      }
    } else if (column.type === "date") {
      return (a, b) => {
        const dateA = new Date(a[prop]);
        const dateB = new Date(b[prop]);

        // @ts-ignore
        if (isNaN(dateA) || isNaN(dateB)) return 0; // fail-safe for invalid dates

        if (column.order === "asc") {
          return dateA.getTime() - dateB.getTime();
        } else if (column.order === "desc") {
          return dateB.getTime() - dateA.getTime();
        } else {
          return 0;
        }
      }
    }
  }

  sort(column: ColumnType, element: HTMLElement) {
    element.onclick = (event) => {
      if (!column.sortable) return
      const target = event.target as HTMLElement;
      if (
        target.closest(".dom-table-header--bottom") ||
        target.closest(".dom-table__resizer") ||
        this.resizingColumn
      ) {
        return;
      }
      if (!column.skipRotateOrder) {
        this.getColumns().forEach((col: ColumnType) => {
          if (col === column) {
            column.order = rotateOrder(column.order);
          } else {
            col.order = undefined;
          }
        });
      }

      let sortedData = undefined;
      if (column.type) {
        sortedData = [...this.table.data]?.sort(this.handleSort(column));
      }

      this.table.customSort.emit({
        column,
        order: column.order,
        rotateOrder,
        data: sortedData,
        sortFn: this.handleSort
      });
    };
  }

  subscribe = () => {
    for (const [key, value] of Object.entries(this.subscriptions)) {
      const {target, callback, options = {}} = value as Subscription
      target?.addEventListener(key, callback, options)
    }
  }

  clearSubscriptions() {
    for (const [key, value] of Object.entries(this.subscriptions)) {
      const {target, callback, options = {}} = value as Subscription
      target?.removeEventListener(key, callback, options)
    }
	}

  rowLevelClick = (data: any) => (event: MouseEvent) => {
    this.table.rowClick.emit({
      data,
      event,
      target: event.target
    });
  }

  getColumnPin = (columnId: string) => {
    if (!columnId) return undefined;

    const column = this.table.columns.find((col: ColumnType) => col.id === columnId);
    if (column) return column.pin;

    const group = this.table.groupService.getItemInGroup(columnId);
    return group?.pin;
  }
}
